@register_feature_layer("options")
class OptionsLayer:
    """Options-implied feature layer (Layer 2).

    Reads IV columns from daily_data (pre-merged by IVSurfaceLayer) or from
    the legacy context["iv_surface"] path. Computes derived features:
    VRP, skew, term slope, IV-RV gap, VVIX-derived, VIX interaction.

for dt in dates:
    d = dt.date() if hasattr(dt, "date") else dt
    is_fomc = d in _FOMC_SET
    nxt = _next_fomc(d)
    if nxt is None:
        dist = 30  # fallback for dates beyond 2026
    elif nxt == d:
        dist = 0
    else:
        dist = _busday_count(d, nxt)

    days_to.append(dist)
    fomc_week.append(1 if dist <= 5 else 0)
    fomc_day.append(1 if is_fomc else 0)
